export const meta = {
  name: 'build-jarvis-f4-csv-export',
  description: 'Build F4 (CSV export) from the design file, then verify on a separate seat',
  phases: [
    { title: 'Build', detail: 'one agent per task, on its tagged tier' },
    { title: 'Verify', detail: 'run VERIFICATION, report evidence' },
  ],
}

const GRADE = args.grade
const DESIGN_FILE = args.designFile
const REPO = args.repo
const M = args.tiers
const VERDICT = { type: 'object', required: ['pass', 'evidence'], properties: { pass: { type: 'boolean' }, evidence: { type: 'string' } } }

const results = await pipeline(
  args.tasks,
  (_, t) => agent(
    `${GRADE}

Implement exactly task ${t.id} from the design file, nothing more.
Design file: ${DESIGN_FILE} (read it first; follow its CONSTRAINTS and test-first steps).
Repo: ${REPO}
Touch ONLY: ${t.files.join(', ')}
Do not commit. Do not run any verify beyond the task's own steps.
Report: files changed, and the final pytest output. If you hit a blocker only a human can resolve, stop and say so.`,
    { model: M[t.build], label: `build:${t.id}`, phase: 'Build' },
  ),
  (built, t) => agent(
    `${GRADE}

Verify task ${t.id} landed in ${REPO}. Design file: ${DESIGN_FILE} — read its CONSTRAINTS and VERIFICATION.
Build agent reported: ${built}
Run, from ${REPO}: \`python -m pytest -q\` and \`python -m shelf export\`. Read exit codes.
Also review the diff (\`git diff\` plus new untracked files) against every CONSTRAINT and that only the listed files changed: ${t.files.join(', ')}.
Do not edit any file. Report the ACTUAL command output as evidence, never a claim. pass=true only if everything holds.`,
    { model: M[args.verifySeat], label: `verify:${t.id}`, phase: 'Verify', schema: VERDICT },
  ).then(v => ({ task: t.id, built, verdict: v })),
)

const done = results.filter(Boolean)
return {
  passed: done.filter(r => r.verdict?.pass),
  failed: done.filter(r => !r.verdict?.pass),
  dropped: args.tasks.length - done.length,
}

